mod solution;

fn main() {
    let cases = [
    (r#"3 + 4 * 2"#, r#"3 4 2 * +"#),
    (r#"2 * 3 + 4"#, r#"2 3 * 4 +"#),
    (r#"
2 * 3 + 4
"#, r#"2 3 * 4 +"#),
    (r#"  
3 + 4 * 2
  "#, r#"3 4 2 * +"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS expression-shunting-yard");
}
